// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// EVOLVE-BLOCK-START
pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    let d = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, d);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize, depth: usize) {
    if hi <= lo { return; }
    let n = hi - lo + 1;
    if n <= 24 { insertion_sort_range(arr, lo, hi); return; }
    if depth == 0 { heap_sort_range(arr, lo, hi); return; }
    let p = partition(arr, lo, hi);
    if p > 0 { introsort(arr, lo, p - 1, depth - 1); }
    introsort(arr, p + 1, hi, depth - 1);
}

fn partition<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize) -> usize {
    if hi - lo >= 2 {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] < arr[lo] { arr.swap(lo, mid); }
        if arr[hi] < arr[lo] { arr.swap(lo, hi); }
        if arr[hi] < arr[mid] { arr.swap(mid, hi); }
        arr.swap(mid, hi);
    }
    let pivot = arr[hi].clone();
    let mut i = lo;
    for j in lo..hi {
        if arr[j] <= pivot { arr.swap(i, j); i += 1; }
    }
    arr.swap(i, hi);
    i
}

fn insertion_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    for i in (low + 1)..=high {
        let mut j = i;
        while j > low && arr[j - 1] > arr[j] {
            arr.swap(j, j - 1);
            j -= 1;
        }
    }
}

fn heap_sort_range<T: Ord>(arr: &mut [T], low: usize, high: usize) {
    let len = high - low + 1;
    for i in (0..len / 2).rev() {
        sift_down(arr, low, i, len);
    }
    for i in (1..len).rev() {
        arr.swap(low, low + i);
        sift_down(arr, low, 0, i);
    }
}

fn sift_down<T: Ord>(arr: &mut [T], base: usize, start: usize, len: usize) {
    let mut root = start;
    loop {
        let child = 2 * root + 1;
        if child >= len { break; }
        let mut swap = root;
        if arr[base + child] > arr[base + swap] { swap = child; }
        if child + 1 < len && arr[base + child + 1] > arr[base + swap] { swap = child + 1; }
        if swap == root { break; }
        arr.swap(base + root, base + swap);
        root = swap;
    }
}
